package com.primehr.rsp.evaluation.application;
import com.primehr.rsp.evaluation.api.CommitteeDtos.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.rsp.evaluation.infrastructure.*; import com.primehr.shared.api.PageResponse; import com.primehr.shared.audit.PrimeHrAuditService; import com.primehr.shared.exception.*; import org.springframework.data.domain.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service @Transactional public class CommitteeServiceImpl implements CommitteeService {
 private final CommitteeRepository committees;private final CommitteeMemberRepository members;private final CommitteeMemberEligibilityService eligibility;private final PrimeHrAuditService audit;
 public CommitteeServiceImpl(CommitteeRepository c,CommitteeMemberRepository m,CommitteeMemberEligibilityService e,PrimeHrAuditService a){committees=c;members=m;eligibility=e;audit=a;}
 @Override @Transactional(readOnly=true)public PageResponse<CommitteeResponse> list(String agency,int page,int size){page(page,size);return PageResponse.from(committees.findByAgencyId(agency,PageRequest.of(page,size,Sort.by("createdAt").descending())),c->response(agency,c));}
 @Override @Transactional(readOnly=true)public CommitteeResponse get(String agency,String id){return response(agency,committee(agency,id));}
 @Override public CommitteeResponse create(String agency,SaveCommittee r,String token,String correlation){if(r.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must not be supplied when creating");validateInput(r);eligibility.validate(r.members(),token);String code=r.code().trim().toUpperCase(Locale.ROOT);if(committees.existsByAgencyIdAndNormalizedCodeAndDefinitionVersion(agency,code,1))throw new IllegalArgumentException("Committee code already exists");Committee c=committees.saveAndFlush(new Committee(agency,r.code(),r.name(),r.legalBasis(),r.minimumVotingMembers(),1,null));replace(agency,c,r.members());CommitteeResponse after=response(agency,c);audit.record(agency,"CREATE_COMMITTEE_DRAFT","PRIME_COMMITTEE",c.getId(),1,c.getVersion(),null,after,null,correlation);return after;}
 @Override public CommitteeResponse update(String agency,String id,SaveCommittee r,String token,String correlation){Committee c=committee(agency,id);version(c.getVersion(),r.recordVersion());validateInput(r);eligibility.validate(r.members(),token);CommitteeResponse before=response(agency,c);c.update(r.code(),r.name(),r.legalBasis(),r.minimumVotingMembers());c=committees.saveAndFlush(c);replace(agency,c,r.members());CommitteeResponse after=response(agency,c);audit.record(agency,"UPDATE_COMMITTEE_DRAFT","PRIME_COMMITTEE",id,c.getDefinitionVersion(),c.getVersion(),before,after,null,correlation);return after;}
 @Override public CommitteeResponse publish(String agency,String id,Publish r,String token,String correlation){Committee c=committee(agency,id);version(c.getVersion(),r.recordVersion());List<CommitteeMember> roster=members.findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(agency,id);validatePublish(c,roster,r.effectiveFrom(),r.effectiveTo());eligibility.validate(roster.stream().map(m->new MemberInput(m.getEmployeeNo(),m.getRole(),m.getRepresentation(),m.getEffectiveFrom(),m.getEffectiveTo())).toList(),token);Committee prior=c.getSupersedesId()==null?null:committee(agency,c.getSupersedesId());if(prior!=null&&!r.effectiveFrom().isAfter(prior.getEffectiveFrom()))throw new IllegalArgumentException("A successor must become effective after its predecessor");CommitteeResponse before=response(agency,c);c.publish(r.effectiveFrom(),r.effectiveTo(),audit.currentActor(),Instant.now());c=committees.saveAndFlush(c);if(prior!=null){prior.supersede(r.effectiveFrom());committees.saveAndFlush(prior);}CommitteeResponse after=response(agency,c);audit.record(agency,"PUBLISH_COMMITTEE","PRIME_COMMITTEE",id,c.getDefinitionVersion(),c.getVersion(),before,after,null,correlation);return after;}
 @Override public CommitteeResponse successor(String agency,String id,Transition r,String correlation){Committee prior=committee(agency,id);version(prior.getVersion(),r.recordVersion());if(prior.getStatus()!=Committee.Status.PUBLISHED)throw new IllegalArgumentException("Only a PUBLISHED committee can have a successor");int next=committees.findByAgencyIdAndNormalizedCodeOrderByDefinitionVersion(agency,prior.getNormalizedCode()).stream().mapToInt(Committee::getDefinitionVersion).max().orElse(0)+1;Committee c=committees.saveAndFlush(new Committee(agency,prior.getCode(),prior.getName(),prior.getLegalBasis(),prior.getMinimumVotingMembers(),next,prior.getId()));List<CommitteeMember> copies=members.findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(agency,id).stream().map(m->new CommitteeMember(agency,c.getId(),m.getEmployeeNo(),m.getRole(),m.getRepresentation(),m.getEffectiveFrom(),m.getEffectiveTo())).toList();members.saveAll(copies);members.flush();CommitteeResponse after=response(agency,c);audit.record(agency,"CREATE_COMMITTEE_SUCCESSOR","PRIME_COMMITTEE",c.getId(),next,c.getVersion(),null,after,null,correlation);return after;}
 private void replace(String agency,Committee c,List<MemberInput> values){members.deleteByAgencyIdAndCommitteeId(agency,c.getId());members.saveAll(values.stream().map(m->new CommitteeMember(agency,c.getId(),m.employeeNo(),m.role(),m.representation(),m.effectiveFrom(),m.effectiveTo())).toList());members.flush();}
 private void validateInput(SaveCommittee r){Set<String> people=new HashSet<>();for(MemberInput m:r.members()){if(!people.add(m.employeeNo().trim().toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("An employee may appear only once in a committee version");if(m.effectiveTo()!=null&&m.effectiveTo().isBefore(m.effectiveFrom()))throw new IllegalArgumentException("Member effectiveTo cannot precede effectiveFrom");}}
 private void validatePublish(Committee c,List<CommitteeMember> roster,LocalDate from,LocalDate to){if(roster.isEmpty())throw new IllegalArgumentException("A committee requires members");validateEffectiveRoster(c,roster,from);}
 static void validateEffectiveRoster(Committee c,List<CommitteeMember> roster,LocalDate date){List<CommitteeMember> active=roster.stream().filter(m->m.effectiveOn(date)).toList();if(active.stream().filter(m->m.getRole()==CommitteeMember.Role.CHAIRPERSON).count()!=1)throw new IllegalArgumentException("Exactly one effective CHAIRPERSON is required");if(active.stream().noneMatch(m->m.getRole()==CommitteeMember.Role.SECRETARIAT))throw new IllegalArgumentException("An effective SECRETARIAT is required");if(active.stream().filter(CommitteeMember::voting).count()<c.getMinimumVotingMembers())throw new IllegalArgumentException("The minimum effective voting membership is not met");}
 private CommitteeResponse response(String agency,Committee c){return new CommitteeResponse(c.getId(),c.getCode(),c.getType().name(),c.getName(),c.getLegalBasis(),c.getDefinitionVersion(),c.getSupersedesId(),c.getStatus().name(),c.getEffectiveFrom(),c.getEffectiveTo(),c.getMinimumVotingMembers(),c.getPublishedBy(),c.getPublishedAt(),c.getVersion(),members.findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(agency,c.getId()).stream().map(m->new MemberResponse(m.getId(),m.getEmployeeNo(),m.getRole().name(),m.getRepresentation(),m.getEffectiveFrom(),m.getEffectiveTo())).toList());}
 private Committee committee(String agency,String id){return committees.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Committee not found"));} private static void version(long a,Long e){if(e==null||a!=e)throw new OptimisticConflictException("Expected recordVersion "+e+" but current version is "+a);} private static void page(int p,int s){if(p<0||s<1||s>100)throw new IllegalArgumentException("Invalid pagination");}
}
